import { EventEmitter } from "node:events";
import { createRequire } from "node:module";
import { parseArgs } from "node:util";
import { failure } from "./failures.js";
import { createDefaultLauncher, resolveDefaultWorkerLauncherKind, } from "./launcher.js";
import { RUNTIME_LIMITS } from "./limits.js";
import { createPrelaunchedBrowserAdapter, } from "./prelaunched-browser.js";
import { startPlaywrightRuntimeProxy } from "./proxy.js";
import { createSandPlaywrightRuntime } from "./supervisor.js";
export const RUN_CODE_TOOL = "browser_run_code";
export const STOCK_RUN_CODE_TOOL = "browser_run_code_unsafe";
export class SandPlaywrightSetupError extends Error {
    constructor(setupFailure, cause) {
        super(cause instanceof Error ? cause.message : String(cause), { cause });
        this.setupFailure = setupFailure;
    }
}
async function setupStep(setupFailure, step) {
    try {
        return await step();
    }
    catch (error) {
        throw new SandPlaywrightSetupError(setupFailure, error);
    }
}
const require = createRequire(import.meta.url);
export function loadCoreBundle() {
    const bundle = require("playwright-core/lib/coreBundle");
    return checkCoreBundle(bundle);
}
export async function checkCoreBundle(bundle) {
    const { tools, server } = bundle;
    const missing = ["BrowserBackend", "filteredTools", "resolveCLIConfigForMCP", "start"].filter((name) => typeof Reflect.get(tools ?? {}, name) !== "function");
    if (tools === undefined || missing.length > 0) {
        throw new Error(`playwright-core coreBundle.tools is missing ${missing.join(", ")}`);
    }
    const idle = Object.assign(new EventEmitter(), { browser: () => undefined });
    const probe = new tools.BrowserBackend({}, idle, [], async () => { });
    try {
        await probe.initialize({ clientName: "sand-closure-check" });
        toolContext(probe);
    }
    finally {
        await probe.dispose();
    }
    return { tools, server };
}
function toolContext(backend) {
    const context = Reflect.get(backend, "_context");
    if (typeof context !== "object" ||
        context === null ||
        typeof Reflect.get(context, "ensureBrowserContext") !== "function") {
        throw new Error("playwright-core BrowserBackend is missing _context.ensureBrowserContext");
    }
    return context;
}
function coreVersion() {
    const { version } = require("playwright-core/package.json");
    return version;
}
export function sandTools(tools, config) {
    const { z } = require("playwright-core/lib/utilsBundle");
    const stockTools = tools
        .filteredTools(config)
        .filter((tool) => tool.schema.name !== STOCK_RUN_CODE_TOOL);
    const runCode = {
        name: RUN_CODE_TOOL,
        title: "Run Playwright code",
        description: "Run inline Playwright page code in a restricted isolated worker.",
        inputSchema: z.object({
            code: z
                .string()
                .max(RUNTIME_LIMITS.codeBytes)
                .describe("An async Playwright function, `async (page) => { ... }`."),
        }),
        type: "action",
    };
    return { stockTools, schemas: [...stockTools.map((tool) => tool.schema), runCode] };
}
export function stockDefaultTimeouts(config) {
    const action = config.timeouts?.action;
    const navigation = config.timeouts?.navigation;
    return action === undefined || navigation === undefined
        ? undefined
        : { actionMs: action, navigationMs: navigation };
}
export function parseServerArgs(argv) {
    const { values } = parseArgs({
        args: [...argv],
        strict: true,
        options: {
            "cdp-endpoint": { type: "string" },
            "timeout-action": { type: "string" },
            "timeout-settle": { type: "string" },
            "timeout-navigation": { type: "string" },
            codegen: { type: "string" },
            "output-dir": { type: "string" },
            "run-code-prewarm": { type: "boolean" },
        },
    });
    const cdpEndpoint = values["cdp-endpoint"];
    if (cdpEndpoint === undefined || !isLoopbackEndpoint(cdpEndpoint)) {
        throw new Error("--cdp-endpoint must be a loopback URL");
    }
    const milliseconds = (value) => {
        if (value !== undefined && !/^\d{1,7}$/u.test(value))
            throw new Error(`invalid timeout ${value}`);
        return value === undefined ? undefined : Number(value);
    };
    return {
        cdpEndpoint,
        timeoutAction: milliseconds(values["timeout-action"]),
        timeoutSettle: milliseconds(values["timeout-settle"]),
        timeoutNavigation: milliseconds(values["timeout-navigation"]),
        codegen: values.codegen,
        outputDir: values["output-dir"],
        runCodePrewarm: values["run-code-prewarm"] === true,
    };
}
export async function runSandPlaywrightMcpServer(argv) {
    const { runCodePrewarm, ...options } = await setupStep("args_rejected", () => parseServerArgs(argv));
    const { tools, server } = await setupStep("closure_mismatch", loadCoreBundle);
    const config = await setupStep("args_rejected", () => tools.resolveCLIConfigForMCP(options, {}));
    const { stockTools, schemas } = await setupStep("closure_mismatch", () => sandTools(tools, config));
    const upstream = await setupStep("browser_attach_failed", () => admitted(createPrelaunchedBrowserAdapter({ server, cdpEndpoint: options.cdpEndpoint })));
    const stockProxy = await setupStep("proxy_failed", () => admitted(startPlaywrightRuntimeProxy({ upstream, mode: "stock" })));
    const launcherKind = resolveDefaultWorkerLauncherKind();
    const unsafe = startUntilRejected(async () => {
        const proxy = await admitted(startPlaywrightRuntimeProxy({ upstream, mode: "unsafe" }));
        return {
            proxy,
            runtime: createSandPlaywrightRuntime({
                proxy: { kind: "prelaunched-browser-proxy", wsEndpoint: proxy.wsEndpoint },
                launcher: afterDroppingStaleClient(proxy, createDefaultLauncher(launcherKind)),
                deadline: proxy,
                defaultTimeouts: stockDefaultTimeouts(config),
            }),
        };
    });
    const runCode = async (args, signal) => {
        const result = await unsafe.start().then(({ runtime }) => runtime.run(args, signal === undefined ? { kind: "none" } : { kind: "cancel", signal }), () => ({
            kind: "failure",
            failure: failure("launch_failed", "Unsafe browser runtime failed to start"),
            stdio: [],
        }));
        const outcome = result.kind === "success"
            ? { result: result.value }
            : { error: { code: result.failure.code, message: result.failure.message } };
        return {
            content: [
                {
                    type: "text",
                    text: JSON.stringify({
                        ...outcome,
                        stdio: result.stdio,
                        workerIsolation: launcherKind,
                    }),
                },
            ],
            isError: result.kind === "failure",
        };
    };
    class BrowserBackend extends tools.BrowserBackend {
        constructor(browser, released) {
            super(config, browser.contexts()[0], stockTools, async () => {
                await browser.close();
                await released;
            });
            this.lost = false;
            this.initialized = false;
            this.once("disconnected", () => {
                this.lost = true;
            });
        }
        async initialize(clientInfo) {
            if (this.initialized)
                return;
            this.initialized = true;
            await super.initialize(clientInfo);
            await toolContext(this).ensureBrowserContext();
        }
        callTool(name, args, signal) {
            return name === RUN_CODE_TOOL ? runCode(args, signal) : super.callTool(name, args, signal);
        }
    }
    const { chromium } = require("playwright-core");
    const backends = createStockBackends({
        proxy: stockProxy,
        connectBrowser: (wsEndpoint) => chromium.connect(wsEndpoint),
        createBackend: (browser, released) => new BrowserBackend(browser, released),
    });
    let exiting = false;
    const exit = async () => {
        if (exiting)
            return;
        exiting = true;
        backends.stop();
        setTimeout(() => process.exit(0), 5_000).unref();
        const started = await unsafe.started();
        await started?.runtime.close();
        await Promise.allSettled([started?.proxy.close(), stockProxy.close()]);
        process.exit(0);
    };
    process.stdin.once("end", () => void exit());
    process.stdin.once("close", () => void exit());
    process.once("SIGINT", () => void exit());
    process.once("SIGTERM", () => void exit());
    const factory = {
        name: "Playwright",
        nameInConfig: "playwright",
        version: coreVersion(),
        toolSchemas: schemas,
        create: (clientInfo) => backends.create(clientInfo),
    };
    await setupStep("stdio_failed", () => tools.start(factory));
    if (runCodePrewarm) {
        void unsafe.start().then(({ runtime }) => runtime.prewarm(), () => undefined);
    }
}
export function afterDroppingStaleClient(proxy, launcher) {
    return {
        launch(proxyEndpoint) {
            proxy.dropClient();
            return launcher.launch(proxyEndpoint);
        },
    };
}
export function startUntilRejected(start) {
    let pending;
    return {
        start() {
            if (pending !== undefined)
                return pending;
            const starting = start();
            pending = starting;
            starting.catch(() => {
                if (pending === starting)
                    pending = undefined;
            });
            return starting;
        },
        async started() {
            return pending?.catch(() => undefined);
        },
    };
}
export function createStockBackends(options) {
    let releaseSlot;
    const connect = async (clientInfo) => {
        const released = new Promise((resolve) => {
            releaseSlot = resolve;
        });
        const browser = await options.connectBrowser(options.proxy.wsEndpoint);
        try {
            const backend = options.createBackend(browser, released);
            await backend.initialize(clientInfo);
            return backend;
        }
        catch (error) {
            await browser.close();
            await released;
            throw error;
        }
    };
    let warm;
    let rewarm;
    let stopped = false;
    options.proxy.onClientDisconnect(() => {
        releaseSlot?.();
        releaseSlot = undefined;
        const clientInfo = rewarm;
        rewarm = undefined;
        if (clientInfo !== undefined && !stopped)
            warm = connect(clientInfo).catch(() => undefined);
    });
    return {
        async create(clientInfo) {
            const warmed = await warm;
            warm = undefined;
            if (warmed?.lost === true)
                void warmed.dispose();
            const backend = warmed !== undefined && !warmed.lost ? warmed : await connect(clientInfo);
            rewarm = clientInfo;
            return backend;
        },
        stop() {
            stopped = true;
        },
    };
}
async function admitted(pending) {
    const result = await pending;
    if (result.kind === "rejected")
        throw new Error(result.failure.message);
    return result.value;
}
const LOOPBACK_HOSTS = new Set(["127.0.0.1", "localhost", "[::1]"]); // pragma: allowlist secret
function isLoopbackEndpoint(value) {
    try {
        const url = new URL(value);
        return (["http:", "https:", "ws:", "wss:"].includes(url.protocol) &&
            LOOPBACK_HOSTS.has(url.hostname) &&
            url.username === "" &&
            url.password === "");
    }
    catch {
        return false;
    }
}
